#include "global.h"
#include "journey_galactic.h"
#include "event_data.h"
#include "journey_gym_scaling.h"
#include "journey_campaign_gates.h"
#include "script.h"
#include "fieldmap.h"
#include "constants/flags.h"
#include "constants/maps.h"
#include "constants/vars.h"
#include "constants/opponents.h"
#include "journey_team_missions.h"

struct JourneyGymCity { u16 map; bool8 kanto; u8 badge; u16 x; u16 y; u8 guide; };
#include "journey_gym_cities.h"
extern const u8 Journey_GymGuide[];

static bool32 RegionalFlag(u16 flag)
{
    return (gSaveBlock1Ptr->flags[flag / 8] >> (flag & 7)) & 1;
}

// Return the first unfinished mandatory event. Neither the active map nor
// the other region's badges may change this regional progression.
static bool32 JourneySpaceCenterComplete(void)
{
    // Do not use the temporary flag consumed by the rival's Rayquaza call.
    return VarGet(VAR_MOSSDEEP_SPACE_CENTER_STATE) == 3;
}

static bool32 JourneyWeatherInstituteComplete(void)
{
    return VarGet(VAR_WEATHER_INSTITUTE_STATE) == 1
        && RegionalFlag(TRAINER_FLAGS_START + TRAINER_SHELLY_WEATHER_INSTITUTE);
}

static bool32 JourneyAquaHideoutComplete(void)
{
    return RegionalFlag(FLAG_TEAM_AQUA_ESCAPED_IN_SUBMARINE)
        && RegionalFlag(TRAINER_FLAGS_START + TRAINER_MATT);
}

static bool32 JourneyMissionComplete(const struct JourneyTeamMission *mission)
{
    u32 i;
    for (i = 0; i < mission->count; i++)
        if (!RegionalFlag(TRAINER_FLAGS_START + mission->trainers[i]))
            return FALSE;
    return TRUE;
}

bool32 JourneyRegionalMissionsComplete(bool32 kanto)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sJourneyTeamMissions); i++)
        if (sJourneyTeamMissions[i].kanto == kanto
            && !JourneyMissionComplete(&sJourneyTeamMissions[i]))
            return FALSE;
    return TRUE;
}

static u32 JourneyNativeCampaignEvent(bool32 kanto, u32 count)
{
    if (kanto == TRUE && count >= 1
        && (!RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_2)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_3)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_4)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_SUPER_NERD_MIGUEL)
            || !RegionalFlag(FLAG_GOT_FOSSIL_FROM_MT_MOON)))
        return 17;
    if (kanto == TRUE && count >= 2
        && (!RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_5)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_6)
            || !RegionalFlag(FLAG_GOT_TM28_FROM_ROCKET)
            || VarGet(VAR_MAP_SCENE_ROUTE24) < 1))
        return 18;
    if (kanto == TRUE && count >= 4
        && (!RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_19)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_20)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_TEAM_ROCKET_GRUNT_21)
            || !RegionalFlag(FLAG_RESCUED_MR_FUJI)
            || VarGet(VAR_MAP_SCENE_POKEMON_TOWER_6F) < 1))
        return 19;
    if (kanto == FALSE && count >= 1
        && (!RegionalFlag(TRAINER_FLAGS_START + TRAINER_GRUNT_PETALBURG_WOODS)
            || VarGet(VAR_PETALBURG_WOODS_STATE) < 1))
        return 20;
    if (kanto == FALSE && count >= 1
        && (!RegionalFlag(TRAINER_FLAGS_START + TRAINER_GRUNT_RUSTURF_TUNNEL)
            || !RegionalFlag(FLAG_RECOVERED_DEVON_GOODS)))
        return 21;
    if (kanto == FALSE && count >= 2
        && (!RegionalFlag(FLAG_DELIVERED_STEVEN_LETTER)))
        return 23;
    if (kanto == FALSE && count >= 2
        && (!RegionalFlag(TRAINER_FLAGS_START + TRAINER_GRUNT_MUSEUM_1)
            || !RegionalFlag(TRAINER_FLAGS_START + TRAINER_GRUNT_MUSEUM_2)
            || !RegionalFlag(FLAG_DELIVERED_DEVON_GOODS)))
        return 22;
    return 0;
}

u32 JourneyPendingCampaignEvent(bool32 kanto)
{
    u32 i, count = JourneyGymBadgeCount(kanto);
    u32 nativeEvent = JourneyNativeCampaignEvent(kanto, count);
    if (nativeEvent && nativeEvent != 19) return nativeEvent;
    if (count >= 2)
    {
        if (kanto && !RegionalFlag(FLAG_HIDE_CELADON_ROCKETS))
            return 1;
        if (!kanto && !RegionalFlag(FLAG_DEFEATED_EVIL_TEAM_MT_CHIMNEY))
            return 3;
    }
    if (nativeEvent) return nativeEvent;
    for (i = 0; i < ARRAY_COUNT(sJourneyTeamMissions); i++)
        if (sJourneyTeamMissions[i].kanto == kanto
            && count >= sJourneyTeamMissions[i].badges
            && !JourneyMissionComplete(&sJourneyTeamMissions[i]))
            return sJourneyTeamMissions[i].event;
    if (kanto)
    {
        if (count >= 6 && !RegionalFlag(FLAG_HIDE_SAFFRON_ROCKETS))
            return 2;
    }
    else
    {
        if (count >= 4 && !JourneyWeatherInstituteComplete())
            return 15;
        if (count >= 5 && !RegionalFlag(FLAG_GROUDON_AWAKENED_MAGMA_HIDEOUT))
            return 4;
        if (count >= 6 && !JourneyAquaHideoutComplete())
            return 16;
        if (count >= 7 && !JourneySpaceCenterComplete())
            return 5;
        if (count >= 7 && !RegionalFlag(FLAG_HIDE_SAFFRON_ROCKETS))
            return 13;
        if (count >= 7 && !RegionalFlag(FLAG_KYOGRE_ESCAPED_SEAFLOOR_CAVERN))
            return 6;
        // Archie starts the crisis; Rayquaza's original Sootopolis scene
        // clears this flag. Preserve that mission for every final gym choice.
        if (count >= 7 && RegionalFlag(FLAG_SYS_WEATHER_CTRL))
            return 14;
    }
    return 0;
}

bool32 JourneyCanChallengeSilph(void)
{
    return JourneyGymBadgeCount(TRUE) >= 6
        && JourneyNativeCampaignEvent(TRUE, 8) == 0
        && RegionalFlag(FLAG_HIDE_CELADON_ROCKETS)
        && JourneyRegionalMissionsComplete(TRUE);
}

bool32 JourneyCanStartArchieAlliance(void)
{
    return JourneyGymBadgeCount(FALSE) >= 7
        && JourneyNativeCampaignEvent(FALSE, 8) == 0
        && JourneyWeatherInstituteComplete()
        && JourneyAquaHideoutComplete()
        && RegionalFlag(FLAG_HIDE_SAFFRON_ROCKETS)
        && JourneySpaceCenterComplete()
        && JourneyRegionalMissionsComplete(FALSE);
}

bool32 JourneyCanAwakenRayquaza(void)
{
    // Exploring the tower must not start the crisis before Archie and the
    // original legendary clash in Sootopolis. Keep every prior mission.
    return JourneyCanStartArchieAlliance()
        && RegionalFlag(FLAG_KYOGRE_ESCAPED_SEAFLOOR_CAVERN)
        && RegionalFlag(FLAG_SYS_WEATHER_CTRL)
        && VarGet(VAR_SOOTOPOLIS_CITY_STATE) >= 2
        && VarGet(VAR_SOOTOPOLIS_CITY_STATE) <= 4
        && VarGet(VAR_SKY_PILLAR_STATE) == 0;
}

void JourneyRayquazaAwakeningPermission(void)
{
    gSpecialVar_Result = JourneyCanAwakenRayquaza();
}

void JourneySilphCoPermission(void)
{
    gSpecialVar_Result = JourneyCanChallengeSilph();
}

void JourneyArchiePermission(void)
{
    gSpecialVar_Result = JourneyCanStartArchieAlliance();
}

void JourneyStartSpaceCenterInvasion(void)
{
    // The original invasion was started by winning a particular gym. It must
    // be reachable before the eighth arbitrary gym, without awarding a badge.
    // Keep completed/in-progress states: never respawn defeated Magma members.
    if (JourneyGymBadgeCount(FALSE) < 7
        || !JourneyWeatherInstituteComplete()
        || !JourneyAquaHideoutComplete()
        || !RegionalFlag(FLAG_GROUDON_AWAKENED_MAGMA_HIDEOUT)
        || JourneySpaceCenterComplete()
        || VarGet(VAR_MOSSDEEP_SPACE_CENTER_STATE) != 0)
        return;
    FlagClear(FLAG_HIDE_SLATEPORT_CITY_HARBOR_PATRONS);
    FlagClear(FLAG_HIDE_MOSSDEEP_CITY_TEAM_MAGMA);
    FlagClear(FLAG_HIDE_MOSSDEEP_CITY_SPACE_CENTER_1F_TEAM_MAGMA);
    FlagClear(FLAG_HIDE_MOSSDEEP_CITY_SPACE_CENTER_2F_TEAM_MAGMA);
    FlagClear(FLAG_HIDE_MOSSDEEP_CITY_SPACE_CENTER_2F_STEVEN);
    FlagSet(FLAG_HIDE_MOSSDEEP_CITY_SPACE_CENTER_1F_STEVEN);
    VarSet(VAR_MOSSDEEP_CITY_STATE, 1);
    VarSet(VAR_MOSSDEEP_SPACE_CENTER_STATE, 1);
}

u32 JourneyCurrentGymGate(void)
{
    u32 i;
    for (i = 0; i < ARRAY_COUNT(sJourneyGymCities); i++)
    {
        const struct JourneyGymCity *city = &sJourneyGymCities[i];
        if (gSaveBlock1Ptr->location.mapGroup == MAP_GROUP(city->map)
            && gSaveBlock1Ptr->location.mapNum == MAP_NUM(city->map))
        {
            u16 first = city->kanto ? FLAG_KANTO_BADGE01_GET : FLAG_BADGE01_GET;
            if (RegionalFlag(first + city->badge))
                return 0; // Already won gyms remain accessible for revisits.
            return JourneyPendingCampaignEvent(city->kanto);
        }
    }
    return 0;
}


static void JourneyStartDevonRecovery(void)
{
    // Start the theft after the first arbitrary Hoenn badge, not just Roxanne.
    if (JourneyGymBadgeCount(FALSE) >= 1
        && JourneyNativeCampaignEvent(FALSE, 1) != 20
        && VarGet(VAR_RUSTBORO_CITY_STATE) == 0)
        VarSet(VAR_RUSTBORO_CITY_STATE, 1);
}

void JourneyKantoLeaguePermission(void)
{
    gSpecialVar_Result = JourneyGalacticLeagueReady();
}

void JourneyHoennLeaguePermission(void)
{
    gSpecialVar_Result = JourneyGalacticLeagueReady();
}

void JourneyRegionalStoryGuide(void)
{
    gSpecialVar_Result = JourneyPendingCampaignEvent(isFrlg);
}

void JourneyUpdateGymGate(void)
{
    u16 flag = isFrlg ? FLAG_HIDE_JOURNEY_KANTO_GYM_GUIDE : FLAG_HIDE_JOURNEY_HOENN_GYM_GUIDE;
    u32 gate;
    if (isFrlg && JourneyGymBadgeCount(TRUE) == 8
        && VarGet(VAR_MAP_SCENE_ROUTE22) < 3)
        VarSet(VAR_MAP_SCENE_ROUTE22, 3);
    if (!isFrlg)
    {
        JourneyStartDevonRecovery();
        JourneyStartSpaceCenterInvasion();
    }
    gate = JourneyCurrentGymGate();
    if (gate)
        FlagClear(flag);
    else
        FlagSet(flag);
}

void JourneyExplainGymGate(void)
{
    gSpecialVar_Result = JourneyCurrentGymGate();
}

bool32 JourneyTryGymDoorGate(s16 x, s16 y)
{
    u32 i;
    if (!JourneyCurrentGymGate())
        return FALSE;
    for (i = 0; i < ARRAY_COUNT(sJourneyGymCities); i++)
    {
        const struct JourneyGymCity *city = &sJourneyGymCities[i];
        if (gSaveBlock1Ptr->location.mapGroup == MAP_GROUP(city->map)
            && gSaveBlock1Ptr->location.mapNum == MAP_NUM(city->map)
            && x == city->x + MAP_OFFSET && y == city->y + MAP_OFFSET)
        {
            // Door warps run before normal object collision in this engine.
            // Intercept the actual entrance as well as providing a visible NPC.
            gSpecialVar_LastTalked = city->guide;
            ScriptContext_SetupScript(Journey_GymGuide);
            return TRUE;
        }
    }
    return FALSE;
}

void JourneyFirstBadgeRewardPermission(void)
{
    gSpecialVar_Result = JourneyGymBadgeCount(TRUE) > 0
        || JourneyGymBadgeCount(FALSE) > 0;
}

