extern const u8 MagmaHideout_4F_EventScript_Tabitha[];
extern const u8 MagmaHideout_4F_EventScript_Maxie[];
extern const u8 MossdeepCity_SpaceCenter_2F_EventScript_Tabitha[];
extern const u8 MossdeepCity_SpaceCenter_2F_EventScript_Maxie[];
extern const u8 MossdeepCity_StevensHouse_EventScript_Steven[];
extern const u8 MtChimney_EventScript_Maxie[];
extern const u8 MtChimney_EventScript_Tabitha[];
extern const u8 RocketHideout_B4F_EventScript_Giovanni[];
extern const u8 Route119_WeatherInstitute_2F_EventScript_Shelly[];
extern const u8 Route120_EventScript_Steven[];
extern const u8 SeafloorCavern_Room3_EventScript_Shelly[];
extern const u8 SootopolisCity_EventScript_Steven[];
extern const u8 SootopolisCity_EventScript_Maxie[];
extern const u8 SootopolisCity_EventScript_Archie[];
extern const u8 GraniteCave_StevensRoom_EventScript_Steven[];
extern const u8 MossdeepCity_SpaceCenter_2F_EventScript_Steven[];
bool32 JourneyStoryObjectVisible(const u8 *script)
{
    if(script==GraniteCave_StevensRoom_EventScript_Steven)return !FlagGet(FLAG_DELIVERED_STEVEN_LETTER);
    if(script==MossdeepCity_SpaceCenter_2F_EventScript_Steven)return JourneyPendingCampaignEvent(FALSE)==5;
    if(script==AquaHideout_B2F_EventScript_Matt)return JourneyPendingCampaignEvent(FALSE)==16;
    if(script==MagmaHideout_4F_EventScript_Tabitha)return JourneyPendingCampaignEvent(FALSE)==4;
    if(script==MagmaHideout_4F_EventScript_Maxie)return JourneyPendingCampaignEvent(FALSE)==4;
    if(script==MossdeepCity_SpaceCenter_2F_EventScript_Tabitha)return JourneyPendingCampaignEvent(FALSE)==5;
    if(script==MossdeepCity_SpaceCenter_2F_EventScript_Maxie)return JourneyPendingCampaignEvent(FALSE)==5;
    if(script==MossdeepCity_StevensHouse_EventScript_Steven)return FlagGet(FLAG_DELIVERED_STEVEN_LETTER) && FlagGet(FLAG_RECEIVED_DEVON_SCOPE) && VarGet(VAR_MOSSDEEP_SPACE_CENTER_STATE)<3;
    if(script==MtChimney_EventScript_Maxie)return JourneyPendingCampaignEvent(FALSE)==3;
    if(script==MtChimney_EventScript_Tabitha)return JourneyPendingCampaignEvent(FALSE)==3;
    if(script==RocketHideout_B4F_EventScript_Giovanni)return JourneyPendingCampaignEvent(TRUE)==1;
    if(script==Route119_WeatherInstitute_2F_EventScript_Shelly)return JourneyPendingCampaignEvent(FALSE)==14;
    if(script==Route120_EventScript_Steven)return FlagGet(FLAG_DELIVERED_STEVEN_LETTER) && !FlagGet(FLAG_RECEIVED_DEVON_SCOPE);
    if(script==SeafloorCavern_Room3_EventScript_Shelly)return JourneyPendingCampaignEvent(FALSE)==6;
    if(script==SootopolisCity_EventScript_Steven)return FlagGet(FLAG_DELIVERED_STEVEN_LETTER) && FlagGet(FLAG_RECEIVED_DEVON_SCOPE) && VarGet(VAR_MOSSDEEP_SPACE_CENTER_STATE)==3;
    if(script==SootopolisCity_EventScript_Maxie)return FlagGet(FLAG_KYOGRE_ESCAPED_SEAFLOOR_CAVERN);
    if(script==SootopolisCity_EventScript_Archie)return FlagGet(FLAG_KYOGRE_ESCAPED_SEAFLOOR_CAVERN);
    return TRUE;
}
